// Todo en UN solo parámetro jsonb: el nodo de Postgres de n8n parte los
// parámetros por coma, y aquí viajan nombres y notas escritos por una persona.
//
// No se valida nada aquí. Si sigue libre esa hora, si el negocio atiende ese
// día, si el servicio existe — todo eso lo decide la base, DENTRO de la misma
// transacción en la que escribe. Comprobarlo aquí sería comprobarlo antes, y
// entre el antes y la escritura cabe otra cita.
const b = $input.first().json.body || $input.first().json;
return [{ json: { payload: JSON.stringify({
  instance: String(b.instance || ''),
  telefono: String(b.telefono || ''),
  nombre:   b.nombre   ? String(b.nombre).trim()   : null,
  servicio: b.servicio ? String(b.servicio).trim() : null,
  inicio:   b.inicio   ? String(b.inicio)          : null,
  notas:    b.notas    ? String(b.notas).trim()    : null,
}) } }];
